do $test$ declare s uuid:='20000000-0000-0000-0000-000000000291';o uuid:='40000000-0000-0000-0000-000000000291';actor uuid:='10000000-0000-0000-0000-000000000291';m uuid:='60000000-0000-0000-0000-000000000291';e uuid:='70000000-0000-0000-0000-000000000291';d uuid:='50000000-0000-0000-0000-000000000291';c uuid:='30000000-0000-0000-0000-000000000291';c2 uuid:='30000000-0000-0000-0000-000000000292';q uuid:=gen_random_uuid();claim jsonb;before_receipt jsonb;due timestamptz;r uuid;begin
