 claim:=public.pitacco_ifood_shipping_test_booking('claim',s,actor,o,jsonb_build_object('id',q,'netValue',8.90));
 perform public.pitacco_ifood_shipping_test_booking('finish',s,actor,o,jsonb_build_object('attempt',claim->>'attempt','http',202));
 perform public.pitacco_ifood_shipping_test_event(gen_random_uuid(),m,e,'REQUEST_DRIVER_SUCCESS',clock_timestamp());
 assert (select logistics_provider='marketplace' from public.deliveries where id=d);
