 assert (select cancel_state='rejected' and state='allocated' from pitacco_private.ifood_shipping_test_bookings where order_id=o);
 assert (select logistics_provider='marketplace' from public.deliveries where id=d);
 claim:=public.pitacco_ifood_cancel_driver_test(s,actor,o,'claim','{}');
 perform public.pitacco_ifood_cancel_driver_test(s,actor,o,'finish',jsonb_build_object('attempt',claim->>'attempt','http',202));
 perform public.pitacco_ifood_shipping_test_event(gen_random_uuid(),m,e,'DELIVERY_CANCELLATION_REQUEST_ACCEPTED',clock_timestamp()-interval '1 minute');
 assert (select logistics_provider='marketplace' from public.deliveries where id=d);
