 assert (select status='accepted' and preparation_status='ready' and gross=25 and receipt->>'payment'='pix' and receipt->'items'=before_receipt->'items' from public.orders where id=o);
 assert (select logistics_provider='loja' and status='pendente' and manual_dispatch_hold and deliver_by=due from public.deliveries where id=d);
